grundbuch_betraglicher_rangumfang <- function(rechtsbetrag=NULL, bezifferter_rangumfang=NULL, rangfall=NULL, einordnungsnachweis=NULL) {
 r <- .geld(rechtsbetrag);g <- .geld(bezifferter_rangumfang);.text(einordnungsnachweis,'einordnungsnachweis');.auswahl(rangfall,'rangfall',c('rangvereinbarung_880','rangvorbehalt_881','vormerkungsumfang_883'));teil <- if(.vergleichen(r,g)<0)r else g
 wert <- list(erfasster_rechtsteil=.bruchteile(teil),nicht_erfasster_rechtsteil=.bruchteile(.subtrahieren(r,teil)),ungenutzter_rangrahmen=.bruchteile(.subtrahieren(g,teil)))
 eingaben <- list(rechtsbetrag=rechtsbetrag, bezifferter_rangumfang=bezifferter_rangumfang, rangfall=rangfall, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_GRUNDBUCH_BETRAGLICHER_RANGUMFANG",eingaben,list(list(operation="Bezifferten Rangumfang auf Rechtsbetrag begrenzen und beide nicht erfassten Restgr\u00f6\u00dfen getrennt ausweisen.")),eingaben)
 ergebnis$hinweise <- list("Nur numerische Aufteilung eines ausdr\u00fccklich bezifferten Rangumfangs: erfasster Teil=min(Rechtsbetrag,Rangumfang), \u00fcbriger Rechtsteil=Rechtsbetrag-erfassterTeil, ungenutzter Rahmen=Rangumfang-erfassterTeil.880Vsch\u00fctzt Zwischenrechte;881IVschr\u00e4nkt den Vorbehalt bei zus\u00e4tzlicher Beeintr\u00e4chtigung ein;883IIbegrenzt relative Unwirksamkeit auf Anspruchsbeeintr\u00e4chtigung. Diese Vorschriften liefern keine allgemeine gesetzliche Geldverteilungsformel allein aus Nominalbetr\u00e4gen. Rechtliche Eintragung/Auslegung und Wirkungen auf fremde Rechte sind vorqualifiziert, kein automatischer vollst\u00e4ndiger Rangtausch oder selbst erfundene ZVG-Erl\u00f6sverteilung.883IIIma\u00dfgeblicheVormerkungseintragung mit vorhandenem879-Paarvergleich verwendbar. Rechte mit nicht vergleichbaren Zins-/Nebenleistungsbestandteilen nicht in eine einzige Zahl pressen, sondern rechtlich sachgerechte Komponenten getrennt rechnen. Keine k\u00fcnstliche transitive Gesamtranggruppe aus einzelnen879-Vergleichen.")
 ergebnis
}
